public class ContadorConcorrente {
    static int counter = 0;

    public static void main(String[] args) throws InterruptedException {
        Thread t1 = new Thread(() -> {
            for (int i = 0; i < 1000; i++) {
                counter++;
            }
        });

        Thread t2 = new Thread(() -> {
            for (int i = 0; i < 1000; i++) {
                counter++;
            }
        });

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Valor esperado: 2000");
        System.out.println("Valor real: " + counter);
    }
}

public class BubbleSortDemo {
    public static void main(String[] args) {
        int[] arr = {64, 34, 25, 12, 22, 11, 90};
        int n = arr.length;

        for (int i = 0; i < n - 1; i++) {
            System.out.println("Pasada " + (i + 1) + ":");
            boolean swapped = false;
            for (int j = 0; j < n - i - 1; j++) {
                if (arr[j] > arr[j + 1]) {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                    swapped = true;
                    System.out.println("  Swap: " + arr[j+1] + " <-> " + arr[j]);
                }
            }
            if (!swapped) break;
            System.out.println("  Resultado: " + java.util.Arrays.toString(arr));
        }

        System.out.println("Array final: " + java.util.Arrays.toString(arr));
    }
}

public class SyncDemo {
    static int counter = 0;
    static final Object lock = new Object();

    public static void main(String[] args) throws InterruptedException {
        // SIN synchronized: valor impredecible
        Thread t1 = new Thread(() -> {
            for (int i = 0; i < 1000; i++) {
                counter++;
            }
        });
        Thread t2 = new Thread(() -> {
            for (int i = 0; i < 1000; i++) {
                counter++;
            }
        });

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Sin sync: " + counter);

        // CON synchronized: valor siempre 2000
        counter = 0;
        Thread t3 = new Thread(() -> {
            for (int i = 0; i < 1000; i++) {
                synchronized (lock) {
                    counter++;
                }
            }
        });
        Thread t4 = new Thread(() -> {
            for (int i = 0; i < 1000; i++) {
                synchronized (lock) {
                    counter++;
                }
            }
        });

        t3.start();
        t4.start();
        t3.join();
        t4.join();

        System.out.println("Con sync: " + counter);
    }
}
